def _hm(arm, d_inner, complex_, gates, gate_bias, total, embedding, backbone):
    d_inner = HM_REWIDTH.get(arm, d_inner)
    mixer = dict(head_subsystems=16, rows=[{'rows': 128, 'decay': 'A', 'complex': complex_, **({'gate': True} if complex_ else {})}], proj_source='main_branch', dt_rank='adaptive', use_g_b=gates, use_g_c=gates)
    if gates:
        mixer.update(gate_act='one_plus', gate_pos='pre')
    mixer.update(d_skip_mode='head', use_trap=True, b_norm=True, c_norm=True, bc_conv=False, bias_gran='none', out_norm=False, ckpt=True, backend='cuda', expand=None, d_inner=d_inner, gate_init=HM_GATE_INIT_20260925)
    old = dict(fracs=[{'rows': 128, 'decay': 'A', 'complex': complex_}], gates=gates, gate_bias=gate_bias, bc_bias=False, gate_act='sigmoid')
    return dict(arm=arm, family='hybrid_mamba', budget_s=8500, note='gate screen row respelled; gates at the NEW default gate_act=one_plus, gate_pos=pre (owner 2026-09-25; the 09-22 row ran sigmoid/post: a new model at the old width)' if gates else 'gate screen row respelled (no gates)', supersedes=dict(manifest=HM_OLD_MANIFEST, ref='main (frozen)', arm=arm, total=total, embedding=embedding, non_embedding=backbone, old_ssm_kwargs_changed=old), kwargs=dict(d_model=256, n_layers=2, d_state=128, d_conv=4, bc_conv=False, tie_word_embeddings=True, mixer_kwargs=mixer))
