def _hm_screen2(arm, d_inner, rows, gates=None, note=''):
    d = _hm('real_off', d_inner, False, bool(gates), False, 0, 0, 0)
    mixer = d['kwargs']['mixer_kwargs']
    mixer.update(rows=rows, d_inner=d_inner)
    if gates:
        mixer.update(gate_act=gates[0], gate_pos=gates[1], gate_init='kaiming_uniform')
    d.update(arm=arm, supersedes=None, note=note)
    return d
